(6458142, 959628, 43774, '<td valign="top">Gorgeous!!!!!!! I love puffins, they are Newfoundland''s provincial bird. I''ve never been this close to one though. Jealous!!</td>', 'Gorgeous!!!!!!! I love puffins, they are Newfoundland''s provincial bird. I''ve never been this close to one though. Jealous!!', '2011-07-01 17:38:43.000000', NULL, 1),
(6458143, 959053, 43774, '<td valign="top">Amazing detail in the wings, excellent capture.</td>', 'Amazing detail in the wings, excellent capture.', '2011-07-01 17:38:46.000000', NULL, 1),
