(6458445, 959834, 96751, '<td valign="top">A tad oversharpened for NG.</td>', 'A tad oversharpened for NG.', '2011-07-02 01:17:22.000000', NULL, 1),
(6458446, 959665, 96751, '<td valign="top">Could definitely see this in NG.  Maybe a touch brighter.</td>', 'Could definitely see this in NG.  Maybe a touch brighter.', '2011-07-02 01:17:38.000000', NULL, 1),
(6458447, 959209, 96751, '<td valign="top">Wonderful heron shot</td>', 'Wonderful heron shot', '2011-07-02 01:17:54.000000', NULL, 1),
(6458448, 959385, 96751, '<td valign="top">How odd that they''re all turned away from the camera!!</td>', 'How odd that they''re all turned away from the camera!!', '2011-07-02 01:18:09.000000', NULL, 1),
(6458449, 959618, 96751, '<td valign="top">So that''s two different spiders and a bee????  Incredible.  Could use a bit of contrast and some shading work.</td>', 'So that''s two different spiders and a bee????  Incredible.  Could use a bit of contrast and some shading work.', '2011-07-02 01:18:55.000000', NULL, 1),
(6458450, 959668, 96751, '<td valign="top">Awesome POV.</td>', 'Awesome POV.', '2011-07-02 01:19:16.000000', NULL, 1),
(6458451, 959019, 96751, '<td valign="top">Is that his tongue????  Might have mentioned that in the title.  A rare sight.</td>', 'Is that his tongue????  Might have mentioned that in the title.  A rare sight.', '2011-07-02 01:19:37.000000', NULL, 1),
(6458452, 959343, 96751, '<td valign="top">Really incredible colors.  Somehow, it doesn''t seem tack sharp in any one place.</td>', 'Really incredible colors.  Somehow, it doesn''t seem tack sharp in any one place.', '2011-07-02 01:20:09.000000', NULL, 1),
(6458453, 959196, 96751, '<td valign="top">How lucky were you!  For me, this is a splendid example of something I''d see in NG, but it needs a bit more pp''ing (contrast, amp up the blue, etc.) to help the eye zone in on the drama of the calving, rather than wandering all over the image.</td>', 'How lucky were you!  For me, this is a splendid example of something I''d see in NG, but it needs a bit more pp''ing (contrast, amp up the blue, etc.) to help the eye zone in on the drama of the calving, rather than wandering all over the image.', '2011-07-02 01:22:52.000000', NULL, 1),
(6458455, 958394, 96751, '<td valign="top">Holy Bison!!  This looks like a diorama at the Natural History Museum!!  Glorious light.  Perfectly pp''d.   A contender for sure.</td>', 'Holy Bison!!  This looks like a diorama at the Natural History Museum!!  Glorious light.  Perfectly pp''d.   A contender for sure.', '2011-07-02 01:26:45.000000', NULL, 1),
(6458456, 959658, 96751, '<td valign="top">Very nicely done.  Could see this in NG, although I have a tiny nit with an overall green tinge, which I''d fix.</td>', 'Very nicely done.  Could see this in NG, although I have a tiny nit with an overall green tinge, which I''d fix.', '2011-07-02 01:27:23.000000', NULL, 1),
(6458457, 959558, 96751, '<td valign="top">Ben, this is such an extraordinary image.  Brutal and fascinating.  Very "in your face" in every sense.</td>', 'Ben, this is such an extraordinary image.  Brutal and fascinating.  Very "in your face" in every sense.', '2011-07-02 01:39:10.000000', NULL, 1),
(6458459, 959792, 96751, '<td valign="top">What a sweet image.  Like one is the echo of the other.</td>', 'What a sweet image.  Like one is the echo of the other.', '2011-07-02 01:39:41.000000', NULL, 1),
(6458461, 959742, 96751, '<td valign="top">This was the day God experimented with hallucinogenic drugs...  Awesome image.  Front page for sure.</td>', 'This was the day God experimented with hallucinogenic drugs...  Awesome image.  Front page for sure.', '2011-07-02 01:40:14.000000', NULL, 1),
(6458462, 958579, 96751, '<td valign="top">This is like a cross between NG and Mad Magazine!!  Excellent color and lighting.  Hilarious face.</td>', 'This is like a cross between NG and Mad Magazine!!  Excellent color and lighting.  Hilarious face.', '2011-07-02 01:41:13.000000', NULL, 1),
(6458466, 959244, 96751, '<td valign="top">I love this, Wendy.  Hope he''s doing well for yo.</td>', 'I love this, Wendy.  Hope he''s doing well for yo.', '2011-07-02 01:41:54.000000', NULL, 1),
(6458467, 959337, 96751, '<td valign="top">This must be an Aussie Possum, ''cause the ones in teh US are not this cute :-)</td>', 'This must be an Aussie Possum, ''cause the ones in teh US are not this cute :-)', '2011-07-02 01:41:57.000000', NULL, 1),
(6458468, 958825, 96751, '<td valign="top">I''m not sure, but is this Yo_Spiff?  Killer portrait.  Regardless of who took it.</td>', 'I''m not sure, but is this Yo_Spiff?  Killer portrait.  Regardless of who took it.', '2011-07-02 01:43:15.000000', NULL, 1),
(6458473, 959794, 96751, '<td valign="top">LOL!  They look like lawn ornaments.</td>', 'LOL!  They look like lawn ornaments.', '2011-07-02 01:44:08.000000', NULL, 1),
(6458474, 959628, 96751, '<td valign="top">Fabulous.  Tack sharp.  Love the droplets and the silver beak-ful.</td>', 'Fabulous.  Tack sharp.  Love the droplets and the silver beak-ful.', '2011-07-02 01:44:10.000000', NULL, 1),
(6458475, 959607, 96751, '<td valign="top">If you''d have identified this structure, it would have "sounded" more NG.  Amazing building.</td>', 'If you''d have identified this structure, it would have "sounded" more NG.  Amazing building.', '2011-07-02 01:44:38.000000', NULL, 1),
(6458476, 959393, 96751, '<td valign="top">Wow.  What an amazing place.</td>', 'Wow.  What an amazing place.', '2011-07-02 01:44:54.000000', NULL, 1),
(6458477, 959495, 96751, '<td valign="top">Fabulous! Incredible moment.</td>', 'Fabulous! Incredible moment.', '2011-07-02 01:45:10.000000', NULL, 1),
(6458478, 959700, 96751, '<td valign="top">The low angle gives this a really sexy feel.</td>', 'The low angle gives this a really sexy feel.', '2011-07-02 01:45:25.000000', NULL, 1),
