(6458490, 959494, 96751, '<td valign="top">A rare case where I feel the color version may have worked better for the challenge.</td>', 'A rare case where I feel the color version may have worked better for the challenge.', '2011-07-02 01:51:29.000000', NULL, 1),
(6458491, 959395, 96751, '<td valign="top">I can totally see a story built around this image.  Love the lone sheep to the left, as if enveloped in a sense of bewilderment.</td>', 'I can totally see a story built around this image.  Love the lone sheep to the left, as if enveloped in a sense of bewilderment.', '2011-07-02 01:52:25.000000', NULL, 1),
(6458492, 959559, 96751, '<td valign="top">A bit exuberant with the contrast...  But a solid capture, which did not need the tweety bird border.</td>', 'A bit exuberant with the contrast...  But a solid capture, which did not need the tweety bird border.', '2011-07-02 01:53:21.000000', NULL, 1),
(6458494, 959684, 96751, '<td valign="top">Candid photography at its best.  A crispness that is practically tactile.  And the two trios who could not inhabit more distant universes.  LOVE this.</td>', 'Candid photography at its best.  A crispness that is practically tactile.  And the two trios who could not inhabit more distant universes.  LOVE this.', '2011-07-02 01:54:25.000000', NULL, 1),
(6458495, 959052, 96751, '<td valign="top">Killer moment.  Just a bit soft on focus.  I think this could have been pp''d to significantly increase the drama.</td>', 'Killer moment.  Just a bit soft on focus.  I think this could have been pp''d to significantly increase the drama.', '2011-07-02 01:54:28.000000', NULL, 1),
(6458496, 959430, 96751, '<td valign="top">Wow.  You can almost see the photographer reflected in the body!!</td>', 'Wow.  You can almost see the photographer reflected in the body!!', '2011-07-02 01:54:53.000000', NULL, 1),
