(6461340, 958981, 124815, '<td valign="top">very sweet shot with a lot of oomph.</td>', 'very sweet shot with a lot of oomph.', '2011-07-04 20:57:44.000000', NULL, 1),
(6461348, 959430, 124815, '<td valign="top">Isn''t this just a regular fly? Dressed to a T? really magnificent attire. Very good picture.</td>', 'Isn''t this just a regular fly? Dressed to a T? really magnificent attire. Very good picture.', '2011-07-04 21:05:42.000000', NULL, 1),
