(6461356, 959562, 124815, '<td valign="top">Letting its "hair" down! fascinating creature. Great shot. perhaps a touch too saturated.</td>', 'Letting its "hair" down! fascinating creature. Great shot. perhaps a touch too saturated.', '2011-07-04 21:19:00.000000', NULL, 1),
(6461359, 959642, 124815, '<td valign="top">The composition is striking. The more I look at this picture, the more it absorbs me. It has a true sacred feeling. Top 10.</td>', 'The composition is striking. The more I look at this picture, the more it absorbs me. It has a true sacred feeling. Top 10.', '2011-07-04 21:25:22.000000', NULL, 1),
