INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6465432, 959618, 88897, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Magnum_za:</b></div><hr/><i> Very unique image. Something for the annals of NG no doubt. Very nice crop/composition/exposure/background. Others may think there''s too much dead space bottom left but I think it helps focus the eyes to the insect story going on here. Is this symbiosis? You got great focus on the bee, extremely shallow DOF, the pollen dust is just too comical. The spider is so close and yet it''s not as pin sharp as the bee. They are in the shade of the flower and getting the exposure correct with a high enough s/s must have been very tricky. It''s a great shot and imo your skills should be rewarded with a page in NG. 8. </i></td></tr></table> <br/>Thank you I appreciate the feedback!  This was the first time to come across the male species of the goldenrod..</td>', 'Originally posted by Magnum_za: Very unique image. Something for the annals of NG no doubt. Very nice crop/composition/exposure/background. Others may think there''s too much dead space bottom left but I think it helps focus the eyes to the insect story going on here. Is this symbiosis? You got great focus on the bee, extremely shallow DOF, the pollen dust is just too comical. The spider is so close and yet it''s not as pin sharp as the bee. They are in the shade of the flower and getting the exposure correct with a high enough s/s must have been very tricky. It''s a great shot and imo your skills should be rewarded with a page in NG. 8.  Thank you I appreciate the feedback!  This was the first time to come across the male species of the goldenrod..', '2011-07-08 13:07:34.000000', NULL, 0),
(6465433, 959795, 54645, '<td valign="top">Congrats on the Brown Penny!</td>', 'Congrats on the Brown Penny!', '2011-07-08 13:09:54.000000', NULL, 0),
