(6465534, 959429, 67697, '<td valign="top">Wow a new PB and a ribbon - awesome!  What a gift for you to be able to catch this scene.  It''s excellent.  Congrats!<br/><br/><i>Message edited by author 2011-07-08 14:07:58.</i></td>', 'Wow a new PB and a ribbon - awesome!  What a gift for you to be able to catch this scene.  It''s excellent.  Congrats!', '2011-07-08 15:07:07.000000', '2011-07-08 15:07:58.000000', 0),
(6465540, 959628, 67697, '<td valign="top">Oh Sara this is so beautiful!  What an amazing capture.  You are so lucky to be able to see these in person.  Congratulations on the blue!</td>', 'Oh Sara this is so beautiful!  What an amazing capture.  You are so lucky to be able to see these in person.  Congratulations on the blue!', '2011-07-08 15:10:32.000000', NULL, 0),
